    x = [(inp >> (8*i)) & 0xFF for i in range(4)]
    y = [0]*4
    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1)
    y[3] = g_function(x[3], y[2], 0)
    y[1] = g_function(x[1] ^ x[0], y[2], 0)
    y[0] = g_function(x[0], y[1], 1)
    out = 0
    for i in range(4):
        out |= y[i] << (8*i)
    return out & 0xFFFFFFFF

def parity(v, m): return bin(v & m).count('1') & 1

N = 1000000
for A, B in [(0x80808080, 0x02000002), (0x02000002, 0x80808080)]:
